"""
import json
import os
import tempfile
import threading
import time

from app.config import CACHE_PATH, CACHE_TTL

# Serialises read/modify/write cycles inside a process; os.replace() keeps the
# on-disk file consistent between processes.  Reentrant so a loader may itself
# resolve other cache keys.
_LOCK = threading.RLock()

_MISSING = object()


def _read_entries(path):
    """Return the parsed cache document, or ``{}`` when absent or unusable."""
    try:
        with open(path, encoding="utf-8") as stream:
            entries = json.load(stream)
    except FileNotFoundError:
        return {}
    except (OSError, ValueError):
        # Unreadable or corrupt cache files are treated as empty and rebuilt.
        return {}
    if not isinstance(entries, dict):
        return {}
    return entries


def _write_entries(path, entries):
    """Persist ``entries`` atomically, creating the cache directory if needed."""
    directory = os.path.dirname(path) or "."
    os.makedirs(directory, exist_ok=True)
    handle, temp_path = tempfile.mkstemp(
        dir=directory, prefix=os.path.basename(path) + ".", suffix=".tmp"
    )
    try:
        with os.fdopen(handle, "w", encoding="utf-8") as stream:
            json.dump(entries, stream)
        os.replace(temp_path, path)
    except BaseException:
        try:
            os.unlink(temp_path)
        except OSError:
            pass
        raise


def _fresh_value(record, now):
    """Return the cached value if ``record`` is still inside the TTL window."""
    if not isinstance(record, dict):
        return _MISSING
    stored_at = record.get("stored_at")
    if not isinstance(stored_at, (int, float)) or isinstance(stored_at, bool):
        return _MISSING
    if "value" not in record:
        return _MISSING
    if now - stored_at >= CACHE_TTL:
        return _MISSING
    return record["value"]


def get_or_load(key, loader, now=None):
    """Return the profile for ``key`` from the shared cache, loading it if stale.

    The cached value is reused while its age is below ``CACHE_TTL`` seconds;
    once it expires (or the key is unknown) ``loader()`` is called, the file
    entry is replaced with the new value and a fresh timestamp, and the value is
    returned.  Because the cache lives on disk, a brand new process reuses
    values stored by a previous one.

    ``now`` may be supplied for deterministic testing; it defaults to
    ``time.time()``.
