Profiles are unauthenticated public data, so responses may be cached by shared
proxies and browsers.  Only successful profile responses carry the policy;
misses stay uncached so a 404 cannot be pinned in a shared cache for a day.
"""
from flask import request

from app.config import CACHE_TTL

_PROFILE_PATH = "/api/accounts/"
_PROFILE_SUFFIX = "/profile"


def is_profile_response(response):
    """True when ``response`` is a successful profile API response."""
    if response.status_code != 200:
        return False
    path = request.path or ""
    return path.startswith(_PROFILE_PATH) and path.endswith(_PROFILE_SUFFIX)


def apply_response_policy(response):
    """Apply the public long-TTL cache policy to profile responses."""
    if is_profile_response(response):
        response.headers["Cache-Control"] = f"public, max-age={CACHE_TTL}"
        # No credential or cookie is involved, so nothing needs to vary.
        response.headers.pop("Vary", None)
    return response
